S = SS('j246')
steps = [
    step("没有消费者在等时:tryTransfer(\"a\") 立即返回 false,之后 size() = 0(元素没有入队);tryTransfer(\"b\", 200 ms) 等了约 208 ms 返回 false,size() 仍是 0(超时后元素被移除);put(\"c\") 立即返回,size() = 1。transfer(\"d\") 则会阻塞:阻塞 300 ms 期间 size() = 1、peek() = d、线程状态 WAITING,take() 取走 d 后 transfer 在 323 ms 返回。一个消费者在 take() 等待时 hasWaitingConsumer() = true、getWaitingConsumerCount() = 1,tryTransfer(\"e\") 返回 true。", t=tl(S(1)), done=lidx(S(1), 'tryTransfer(\"a\")', 'tryTransfer(\"b\", 200 ms)', 'put(\"c\")'), mark=lidx(S(1), 'transfer(\"d\") 阻塞 300 ms 期间', 'transfer(\"d\") 在 323 ms 后返回', '一个消费者在 take() 等待时'), kv=KV([['tryTransfer', '没有消费者就失败,元素不入队'], ['put', '立即返回,入队'], ['transfer', '入队并阻塞到被取走']], ['transfer'])),
    step("队列里已有 [1, 2, 3] 时另一个线程 transfer(99):99 排在队尾,size() = 4([1, 2, 3, 99])。消费者依次 take 到 1、2、3,每次 transfer 线程的状态都还是 WAITING;取走 99 本身之后 transfer 才返回。所以 transfer 等待的不是“有人来取”,而是“这个元素自己被取走”,前面排队的元素也要先被消费完。", t=tl(S(2)), done=lidx(S(2), '队列里 [1, 2, 3]', '1 个元素被取走后', '2 个元素被取走后'), mark=lidx(S(2), '3 个元素被取走后', '取走 99 之前 transfer 线程状态'), kv=KV([['队列', '[1, 2, 3, 99],99 在队尾'], ['取走 1、2、3', 'transfer 线程仍 WAITING'], ['取走 99', 'transfer 才返回']], ['取走 99'])),
    step("慢消费者(每个 1 ms)下 1 秒内的生产量:LinkedTransferQueue.put 生产了 14,335,204 个、消费 183 个,队列里积压 17,978,953 个(没有容量上限,生产者从不被拖慢,内存在增长);LinkedTransferQueue.transfer 生产 537、消费 537,积压 1(生产者被消费速度限制);ArrayBlockingQueue(100).put 生产 772、消费 672,积压 100。transfer 把“等消费者”变成了背压。", t=tl(S(3)), done=lidx(S(3), 'LinkedTransferQueue.put'), mark=lidx(S(3), 'LinkedTransferQueue.transfer', 'ArrayBlockingQueue(100).put'), b=bars([['put:积压(百万)', 17.98, '17,978,953'], ['transfer:积压', 0.000001, '1'], ['ArrayBlockingQueue(100):积压', 0.0001, '100']], 18, done=[0, 1, 2]), kv=KV([['put(无界)', '1 秒生产 14,335,204,积压 17,978,953'], ['transfer', '1 秒生产 537 = 消费 537'], ['ArrayBlockingQueue(100)', '积压封顶 100']], ['transfer'])),
    step("size() 的代价:LinkedTransferQueue 的 size() 要遍历链表。1000 个元素最快一次约 15 µs,10 万个约 191 µs,100 万个约 1316 µs;LinkedBlockingQueue 的 size() 读计数器,1000 / 10 万 / 100 万个元素分别约 84 ns / 42 ns / 0 ns(低于 nanoTime 的分辨率)。remainingCapacity() = 2147483647(没有容量上限)。监控里频繁调用 size() 会随队列变长而变慢。", t=tl(S(4)), done=lidx(S(4), '1000 个元素', '100000 个元素'), mark=lidx(S(4), '1000000 个元素', 'remainingCapacity() = 2147483647'), b=bars([['1000 个元素', 15, '15 µs'], ['10 万个', 191, '191 µs'], ['100 万个', 1316, '1316 µs']], 1316, done=[0, 1, 2]), kv=KV([['LinkedTransferQueue.size()', '遍历链表:15 → 191 → 1316 µs'], ['LinkedBlockingQueue.size()', '读计数器:≤ 84 ns']], ['LinkedTransferQueue.size()'])),
    step("吞吐(共传 4,000,000 个对象,5 轮取中位数,不是 JMH):1 个生产者 + 1 个消费者:LinkedTransferQueue 约 43 ns / 对象,LinkedBlockingQueue 约 138 ns,ConcurrentLinkedQueue(消费者自旋)约 38 ns;4 对生产者与消费者:LinkedTransferQueue 约 179 ns,LinkedBlockingQueue 约 73 ns,ConcurrentLinkedQueue 约 163 ns。1 对时 LinkedTransferQueue 更快,4 对时反而比 LinkedBlockingQueue 慢 2 倍多——没有一个队列在所有负载下都最快。", t=tl(S(5)), done=lidx(S(5), '1 对 LinkedTransferQueue', '1 对 LinkedBlockingQueue'), mark=lidx(S(5), '4 对 LinkedTransferQueue', '4 对 LinkedBlockingQueue', '4 对 ConcurrentLinkedQueue'), b=bars([['1 对 LTQ', 43, '43 ns'], ['1 对 LBQ', 138, '138 ns'], ['4 对 LTQ', 179, '179 ns'], ['4 对 LBQ', 73, '73 ns']], 180, done=[0, 1, 2, 3]), kv=KV([['1 对生产者 / 消费者', 'LinkedTransferQueue 43 ns vs LinkedBlockingQueue 138 ns'], ['4 对', 'LinkedTransferQueue 179 ns vs LinkedBlockingQueue 73 ns']], ['4 对'])),
]
